        export_jobs: RwLock::new(HashMap::new()),
    });

    let protected = Router::new()
        .route("/v1/ingest", post(trigger_ingest))
        .route("/v1/ingest/batch", post(trigger_batch_ingest))
        .route("/v1/normalize", post(trigger_normalize))
