            let records = state
                .repo
                .query_decoded_events(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_fills" => {
            let records = state
                .repo
                .query_hl_fill_records(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_funding" => {
