    check_wallet_allowed(&wallet, &state.allowed_wallets)?;

    let tx = state
        .repo
        .get_transaction_by_hash(&wallet, &tx_hash)
        .await
        .map_err(AppError::internal)?;

    match tx {
        Some(tx) => Ok(Json(tx)),
        None => Err(AppError::not_found("Transaction not found")),
    }
}

async fn get_wallet_stats(
