        .await
        .map_err(AppError::internal)?;
    Ok(Json(networks))
}

async fn get_network(
    State(state): State<Arc<AppState>>,
    Path(network_id): Path<String>,
) -> Result<Json<Network>, AppError> {
    let network = state
