    for r in records {
        buf.push_str(&format!(
            "{},{},{},{},{},{},{},{},{},{},{}\n",
            r.id,
            r.raw_transaction_id
                .map(|u| u.to_string())
                .unwrap_or_default(),
            csv_escape(&r.network),
